"""The command reference (docs/reference.md), generated by tools/make_reference.py from the
command table and the property registry; and the guides' examples, which must compile."""

from __future__ import annotations

import importlib.util
import re
import sys
from collections import Counter
from pathlib import Path
from types import ModuleType

import pytest

from wordgenx.commands.builtin import COMMANDS
from wordgenx.compiler import build

ROOT = Path(__file__).resolve().parents[1]
GUIDES = sorted((ROOT / "docs" / "guide").glob("*.md"))


def make_reference() -> ModuleType:
    spec = importlib.util.spec_from_file_location(
        "make_reference", ROOT / "tools" / "make_reference.py"
    )
    assert spec is not None and spec.loader is not None  # noqa: PT018
    module = importlib.util.module_from_spec(spec)
    sys.modules["make_reference"] = module
    spec.loader.exec_module(module)
    return module


def test_the_reference_is_up_to_date() -> None:
    expected = make_reference().render()
    current = (ROOT / "docs" / "reference.md").read_text("utf-8")
    assert current == expected, "docs/reference.md is stale: run python tools/make_reference.py"


def test_every_command_has_one_topic() -> None:
    listed = Counter(name for names in make_reference().CATEGORIES.values() for name in names)
    assert set(listed) == set(COMMANDS), set(listed) ^ set(COMMANDS)
    assert [name for name, count in listed.items() if count > 1] == []


def test_every_option_is_described() -> None:
    missing = [
        f"\\{spec.name}[{option.name}]"
        for spec in COMMANDS.values()
        for option in spec.options
        if not option.doc
    ]
    assert missing == []


EXAMPLE = re.compile(r"^(`{3,})wgx\n(.*?)^\1$", re.MULTILINE | re.DOTALL)


def _examples() -> list[tuple[str, str]]:
    found: list[tuple[str, str]] = []
    for guide in GUIDES:
        text = guide.read_text("utf-8")
        for number, match in enumerate(EXAMPLE.finditer(text), 1):
            found.append((f"{guide.stem}-{number}", match.group(2)))
    return found


@pytest.mark.parametrize(("name", "source"), _examples(), ids=[n for n, _ in _examples()])
def test_guide_examples_compile(name: str, source: str) -> None:
    """Every ```wgx block of the guides compiles without errors or warnings (blocks that are
    fragments, or show a mistake, are written ```text)."""
    data, result = build(source, ROOT / "examples")
    assert data is not None, result.render_diagnostics()
    assert result.diagnostics == (), result.render_diagnostics()
